const AGENTNAME={vaso:'Vasopressin', adr:'Adrenaline', dobut:'Dobutamine', milrin:'Milrinone'};

const FUND=[
  ['c_acid','Acidosis — pH <7.2 blunts the catecholamine response'],
  ['c_k','K⁺ derangement — correct and recheck'],
  ['c_cal','Mg²⁺ / ionised Ca²⁺ low — replace (Ca²⁺ supports contractility and tone)'],
  ['c_temp','Hypothermia — rewarm'],
  ['c_hb','Anaemia — transfuse to target'],
  ['c_av','Restore AV synchrony — atrial / AV-sequential pacing (Module 06)'],
];

function css(v){
  var m=THEME_LIGHT?THEMECOL.light:THEMECOL.dark;
  if(m[v]!=null)return m[v];
  return getComputedStyle(document.documentElement).getPropertyValue(v).trim();
}

function tile(val,lab,sub,color){
  return `<div class="score"><div class="v mono"${color?` style="color:${color}"`:''}>${val}</div><div class="l">${lab}</div><div class="s">${sub}</div></div>`;
}

function fmt(x,p){
  return isNaN(x)?'—':x.toFixed(p);
}

function goalChip(val,lab,cls){
  const c=val===null?'':cls;
  return `<span class="rung ${c}">${lab}</span>`;
}

function goals(s,d){
  const G=[];
  const push=(has,ok,warn,lab)=>{ if(!has){G.push(goalChip(null,lab,''));return;} G.push(goalChip(1,lab, ok?'done':warn?'miss':'bad')); };
  push(!isNaN(s.map),   s.map>=65, s.map>=60, 'MAP≥65');
  push(!isNaN(s.ci),    s.ci>=2.2, s.ci>=2.0, 'CI≥2.2');
  push(!isNaN(d.cpo),   d.cpo>=0.6, d.cpo>=0.5, 'CPO≥0.6');
  const lacOk=(!isNaN(s.lac)&&s.lac<2)||(!isNaN(d.lacRate)&&d.lacRate>=10);
  const lacWarn=(!isNaN(s.lac)&&s.lac<4)&&!(s.lactTrend==='rising');
  push(!isNaN(s.lac)||!isNaN(d.lacRate), lacOk, lacWarn, 'Lactate↓');
  push(!isNaN(s.svo2), s.svo2>=65, s.svo2>=60, 'SvO₂≥65');
  push(!isNaN(d.o2er), d.o2er<=0.3, d.o2er<=0.4, 'O₂ER≤0.3');
  push(!isNaN(d.do2i), d.do2i>=500, d.do2i>=400, 'DO₂i≥500');
  push(!isNaN(s.uo),   s.uo>=0.5, s.uo>=0.3, 'UO≥0.5');
  return G.join('');
}

function scores(s){
  const g=k=>s.inf[k].on&&!isNaN(s.inf[k].dose)?s.inf[k].dose:0;
  const vasoKgMin=s.inf.vaso.on&&!isNaN(s.inf.vaso.dose)?s.inf.vaso.dose/s.wt:0;
  const vis=g('dopa')+g('dobut')+100*(g('adr')+g('norad'))+10*g('milrin')+10000*vasoKgMin;
  const nee=g('norad')+g('adr')+g('dopa')/100+(s.inf.vaso.on&&!isNaN(s.inf.vaso.dose)?s.inf.vaso.dose*2.5:0);
  return {vis,nee};
}

function deriv(s){
  const bsa=(!isNaN(s.wt)&&!isNaN(s.ht))?0.007184*Math.pow(s.wt,0.425)*Math.pow(s.ht,0.725):NaN;
  const co=(!isNaN(s.ci)&&!isNaN(bsa))?s.ci*bsa:NaN;
  const cpo=(!isNaN(s.map)&&!isNaN(co))?(s.map*co)/451:NaN;
  const mpap=(!isNaN(s.pasp)&&!isNaN(s.padp))?s.padp+(s.pasp-s.padp)/3:NaN;
  const papi=(!isNaN(s.pasp)&&!isNaN(s.padp)&&!isNaN(s.cvp)&&s.cvp>0)?(s.pasp-s.padp)/s.cvp:NaN;
  const pvr=(!isNaN(mpap)&&!isNaN(s.paop)&&!isNaN(co)&&co>0)?(mpap-s.paop)*80/co:NaN;
  const svrCalc=(!isNaN(s.map)&&!isNaN(s.cvp)&&!isNaN(co)&&co>0)?(s.map-s.cvp)*80/co:NaN;
  const svri=!isNaN(s.svri)?s.svri:((!isNaN(svrCalc)&&!isNaN(bsa))?svrCalc*bsa:NaN);
  const svriCalc=isNaN(s.svri)&&!isNaN(svri);
  const sv=(!isNaN(co)&&!isNaN(s.hr)&&s.hr>0)?co/s.hr*1000:NaN;
  const svi=(!isNaN(sv)&&!isNaN(bsa))?sv/bsa:NaN;
  const lvswi=(!isNaN(svi)&&!isNaN(s.map)&&!isNaN(s.paop))?svi*(s.map-s.paop)*0.0136:NaN;
  const rvswi=(!isNaN(svi)&&!isNaN(mpap)&&!isNaN(s.cvp))?svi*(mpap-s.cvp)*0.0136:NaN;
  const cao2=(!isNaN(s.hb)&&!isNaN(s.sao2))?1.34*(s.hb/10)*(s.sao2/100):NaN;
  const do2i=(!isNaN(s.ci)&&!isNaN(cao2))?s.ci*cao2*10:NaN;
  const o2er=(!isNaN(s.sao2)&&!isNaN(s.svo2)&&s.sao2>0)?(s.sao2-s.svo2)/s.sao2:NaN;
  const dpg=(!isNaN(s.padp)&&!isNaN(s.paop))?s.padp-s.paop:NaN;
  const tpg=(!isNaN(mpap)&&!isNaN(s.paop))?mpap-s.paop:NaN;
  const cpp=(!isNaN(s.dbp)&&!isNaN(s.paop))?s.dbp-s.paop:NaN;
  const lacClr=(!isNaN(s.prevlac)&&!isNaN(s.lac)&&s.prevlac>0)?(s.prevlac-s.lac)/s.prevlac*100:NaN;
  const lacRate=(!isNaN(lacClr)&&!isNaN(s.dth)&&s.dth>0)?lacClr/s.dth:NaN;
  return {bsa,co,cpo,mpap,papi,pvr,svr:svrCalc,svri,svriCalc,sv,svi,lvswi,rvswi,cao2,do2i,o2er,dpg,tpg,cpp,lacClr,lacRate};
}

function phenotype(s,d){
  const f=s.flags;
  if(f.tamp) return {name:'TAMPONADE',col:'--alarm',conf:'mechanical',mech:true};
  if(f.sam)  return {name:'LVOT / SAM',col:'--alarm',conf:'obstructive · invert',mech:true};
  if(f.rvot) return {name:'RVOT OBSTRUCTION',col:'--alarm',conf:'obstructive · invert',mech:true};
  const svri=(!isNaN(s.svri))?s.svri:(d?d.svri:NaN);
  const haveH=!isNaN(s.ci)&&!isNaN(svri);
  const rv=f.rv||(!isNaN(s.cvp)&&!isNaN(s.paop)&&s.cvp>s.paop&&s.cvp>=12)||(d&&!isNaN(d.papi)&&d.papi<1.0);
  const lv=f.lv||(d&&!isNaN(d.lvswi)&&d.lvswi<25&&!isNaN(s.ci)&&s.ci<2.2);
  if(haveH){
    const low=s.ci<2.2, vaso=svri<1800, high=svri>2400;
    if(rv&&lv) return {name:'MIXED / BIVENT',col:'--violet',conf:'CI+SVRI+echo'};
    if(rv&&vaso&&low) return {name:'MIXED / BIVENT',col:'--violet',conf:'RV + low tone'};
    if(rv) return {name:'RV FAILURE',col:'--warn',conf:'CI+SVRI+PA'};
    if(low&&vaso) return {name:(lv?'MIXED / BIVENT':'VASOPLEGIA'),col:(lv?'--violet':'--cyan'),conf:'CI+SVRI'};
    if(low&&high) return {name:'LV FAILURE',col:'--warn',conf:'CI+SVRI'};
    if(vaso) return {name:'VASOPLEGIA',col:'--cyan',conf:'SVRI low, CI ok'};
    if(low) return {name:'LV FAILURE',col:'--warn',conf:'CI low'};
    return {name:'ADEQUATE CO',col:'--go',conf:'CI/SVRI in range'};
  }
  if(rv&&lv) return {name:'MIXED / BIVENT',col:'--violet',conf:'echo/PA only — add CI/SVRI'};
  if(rv) return {name:'RV FAILURE',col:'--warn',conf:'echo/PA only — add CI/SVRI'};
  if(lv) return {name:'LV FAILURE',col:'--warn',conf:'echo only — add CI/SVRI'};
  return {name:'INDETERMINATE',col:'--dim',conf:'enter CI + SVRI'};
}

function scai(s,d,anySupport){
  const hypo=!isNaN(s.map)&&s.map<65;
  const lactElev=!isNaN(s.lac)&&s.lac>2, lactHigh=!isNaN(s.lac)&&s.lac>4;
  const poorClr=d&&!isNaN(d.lacRate)&&d.lacRate<10;
  const rising=s.lactTrend==='rising'||(d&&!isNaN(d.lacClr)&&d.lacClr<0);
  const hypoperf=lactElev||(!isNaN(s.svo2)&&s.svo2<60)||(!isNaN(s.uo)&&s.uo<0.5)||(!isNaN(s.ci)&&s.ci<2.2)
    ||(d&&!isNaN(d.cpo)&&d.cpo<0.6)||(d&&!isNaN(d.o2er)&&d.o2er>0.4)||(d&&!isNaN(d.do2i)&&d.do2i<300);
  if(s.flags.arrest) return {s:'E',l:'Extremis — refractory / peri-arrest'};
  if(hypoperf&&anySupport&&(rising||lactHigh||poorClr)) return {s:'D',l:'Deteriorating on support'};
  if(hypoperf&&(hypo||anySupport)) return {s:'C',l:'Classic — hypoperfusion needing support'};
  if(hypo&&!hypoperf) return {s:'B',l:'Beginning — hypotension, no hypoperfusion'};
  return {s:'A',l:'At risk'};
}

function rung(s,key){
  const i=s.inf[key];
  if(!i.on) return 'off';
  if(isNaN(i.dose)||i.dose<=0) return 'sub';
  if(DOSEMIN[key]!==undefined && i.dose<DOSEMIN[key]) return 'sub';
  return 'done';
}

function ladderState(s){
  const defs=[['Vasopressin','vaso'],['Adrenaline','adr'],['Dobutamine','dobut'],['Milrinone','milrin']];
  const rungs=defs.map(x=>({name:x[0],key:x[1],state:rung(s,x[1])}));
  return {rungs, complete:rungs.every(r=>r.state==='done')};
}

function startOrder(s,d,ph,L){
  const hypo=!isNaN(s.map)&&s.map<65;
  const stOf=k=>{const r=L.rungs.find(x=>x.key===k);return r?r.state:'off';};
  const n=ph.name;
  let order=[], why={}, deferred=false, note='';
  if(ph.mech){
    deferred=true;
    if(n==='TAMPONADE'){ note='Mechanical \u2014 surgical drainage / re-exploration first. Pressors only as a holding measure; the inotrope ladder is deferred until the tamponade is relieved.'; }
    else if(n==='RVOT OBSTRUCTION'){ note='Dynamic RVOT (infundibular) obstruction is an INVERTED state \u2014 catecholamines deepen the gradient. Stop or cut inotropes, fill the RV, slow the rate, and hold systemic / RV-coronary pressure with a pure vasoconstrictor (noradrenaline or vasopressin); \u03b2-blockade once filled. Exclude a FIXED cause (conduit kink, thrombus, compression) that needs a mechanical fix.'; }
    else { note='SAM / LVOT obstruction is an INVERTED state \u2014 do not climb the inotrope ladder. Stop or cut inotropes, give volume, slow the rate, and raise afterload with a pure vasoconstrictor (phenylephrine or vasopressin).'; }
    return {order, next:null, nextState:'off', deferred, note, why};
  }
  if(n==='VASOPLEGIA'){
    order=['vaso','adr','dobut','milrin'];
    why={vaso:'restores vascular tone and spares catecholamines (VANCS)', adr:'adds inotropy + pressor if a low-output component emerges', dobut:'only if output falls \u2014 it vasodilates', milrin:'only if a low-output component emerges \u2014 it will worsen the low tone'};
    note='Vasopressin is the preferred second pressor here (after first-line noradrenaline).';
  } else if(n==='RV FAILURE'){
    order=hypo?['vaso','milrin','adr','dobut']:['milrin','vaso','adr','dobut'];
    why={vaso:'defends systemic (RV coronary) perfusion and is PVR-sparing \u2014 breaks the ischaemic spiral', milrin:'RV inodilator that also lowers PVR', adr:'for the refractory RV', dobut:'inotrope alternative if milrinone hypotension limits'};
    note='Preferred RV pairing: milrinone + vasopressin. Reduce PVR in parallel (O\u2082, correct hypercarbia / acidosis, iNO). Adrenaline is later-line \u2014 if you add low-dose adrenaline, read the lactate alongside glucose (type-B trap, Module 04).';
  } else if(n.indexOf('MIXED')>=0){
    order=['vaso','adr','milrin','dobut'];
    why={vaso:'restore tone first \u2014 catecholamine-sparing', adr:'inotropy + pressor for the biventricular low-output state', milrin:'add if an RV / afterload component dominates and BP tolerates', dobut:'inotrope alternative'};
    note='Noradrenaline assumed first-line.';
  } else if(n==='LV FAILURE'){
    order=hypo?['dobut','adr','milrin','vaso']:['milrin','dobut','adr','vaso'];
    why=hypo?{dobut:'\u03b2\u2081 inotropy without the vasodilation of milrinone while MAP is low', adr:'potent inotrope + pressor for the refractory low-output LV', milrin:'once MAP is secured \u2014 adds afterload reduction', vaso:'to defend MAP against inodilator vasodilation'}:{milrin:'inodilator \u2014 augments while unloading the afterload-sensitive LV', dobut:'\u03b2\u2081 inotropy alternative', adr:'for the refractory LV', vaso:'to hold MAP if the inodilator drops it'};
    note='Reduce afterload / consider IABP before piling on inotrope (Module 04). Noradrenaline assumed first-line for perfusion pressure.';
  } else if(n==='ADEQUATE CO'){
    order=['vaso','adr','dobut','milrin'];
    return {order, next:null, nextState:'off', deferred:true, note:'Output is adequate \u2014 no inotrope escalation indicated. Treat the patient, not the number.', why:{}};
  } else {
    order=['vaso','adr','dobut','milrin'];
    why={vaso:'if vasodilated and hypotensive', adr:'if low-output needing pressor support', dobut:'if low-output with adequate tone', milrin:'inodilator if BP tolerates'};
    note='Phenotype unresolved \u2014 add CI / SVRI to direct the order.';
  }
  let next=null, nextState='off';
  for(let idx=0; idx<order.length; idx++){ const st=stOf(order[idx]); if(st!=='done'){ next=order[idx]; nextState=st; break; } }
  return {order, next, nextState, deferred, note, why};
}

function computeRecs(s,d,sc,ph,st,L){
  const recs=[];
  const hypo=!isNaN(s.map)&&s.map<65;
  const persistLow=(!isNaN(s.lac)&&s.lac>2)||(!isNaN(s.ci)&&s.ci<2.2)||(!isNaN(s.svo2)&&s.svo2<60)||(!isNaN(d.cpo)&&d.cpo<0.6)||(!isNaN(d.o2er)&&d.o2er>0.4);

  if(s.flags.arrest){
    recs.push({c:'alarm',t:'SCAI E — mobilise MCS in parallel now',
      w:'Do not wait to complete the drug ladder. Activate the MCS/ECMO pathway and continue resuscitation simultaneously.',
      i:['VA-ECMO for arrest / refractory mixed shock','Call surgeon + perfusion','Maintain coronary perfusion pressure while cannulating']});
  }
  const fundOn=FUND.filter(x=>s.fund[x[0]]);
  if(fundOn.length){
    recs.push({c:'warn',t:'Correct reversible contributors first',
      w:'These blunt the vasoactive response and mimic refractoriness — optimise before climbing the ladder or escalating to MCS.',
      i:fundOn.map(x=>x[1])});
  }
  // agent ceilings
  const over=INF.filter(x=>s.inf[x.id].on&&!isNaN(s.inf[x.id].dose)&&DOSEMAX[x.id]!==undefined&&s.inf[x.id].dose>DOSEMAX[x.id]);
  if(over.length){
    recs.push({c:'warn',t:'Agent(s) above usual ceiling',
      w:'Diminishing return and rising ischaemic / arrhythmic risk beyond these rates — add a different mechanism or escalate rather than pushing dose.',
      i:over.map(x=>x.nm+' > '+DOSEMAX[x.id]+' '+x.u)});
  }

  if(ph.mech && ph.name==='TAMPONADE'){
    recs.push({c:'alarm',t:'Tamponade / clot — this is surgical',
      w:'Escalating inotropes will not fix a mechanical problem and may harm.',
      i:['Urgent echo + call surgeon','Prepare for re-exploration / chest re-opening','Bridge with volume ± vasopressor only']});
  }
  if(ph.mech && ph.name==='LVOT / SAM'){
    const inos=[]; if(s.inf.dobut.on)inos.push('dobutamine'); if(s.inf.milrin.on)inos.push('milrinone'); if(s.inf.adr.on)inos.push('adrenaline'); if(s.inf.dopa.on)inos.push('dopamine');
    recs.push({c:'alarm',t:'LVOT / SAM — INVERT your management',
      w:'Small hyperdynamic LV with dynamic obstruction. Everything you would do for a cold LV is wrong here.',
      i:[(inos.length?'STOP / reduce '+inos.join(', ')+' — inotropes worsen the gradient':'Do NOT start inotropes'),
        'Fill — increase preload','Slow the rate; restore AV synchrony, treat AF',
        'Raise afterload with a PURE vasoconstrictor (phenylephrine, or noradrenaline)','Consider β-blockade once filled']});
  }

  if(ph.mech && ph.name==='RVOT OBSTRUCTION'){
    const inos=[]; if(s.inf.dobut.on)inos.push('dobutamine'); if(s.inf.milrin.on)inos.push('milrinone'); if(s.inf.adr.on)inos.push('adrenaline'); if(s.inf.dopa.on)inos.push('dopamine');
    recs.push({c:'alarm',t:'RVOT obstruction — INVERT your management',
      w:'Dynamic infundibular (subpulmonary) obstruction — a hyperdynamic, under-filled RV. Catecholamines deepen the gradient (the opposite of RV-failure management).',
      i:[(inos.length?'STOP / reduce '+inos.join(', ')+' — inotropes worsen the infundibular gradient':'Do NOT start inotropes'),
        'Fill the RV — restore preload (the obstruction is preload-dependent)',
        'Slow the rate; restore AV synchrony',
        'Hold systemic / RV-coronary pressure with a PURE vasoconstrictor (noradrenaline or vasopressin)',
        '\u03b2-blockade (esmolol) once filled to quieten the infundibulum',
        'Exclude a FIXED cause (conduit kink / thrombus / compression) \u2014 that needs a mechanical fix']});
  }

  if(!ph.mech){
    if(persistLow||hypo){
      recs.push({c:'info',t:'Perfusion',w:`${hypo?'MAP below 65. ':''}${persistLow?'Markers of hypoperfusion present.':''} Phenotype-directed plan below.`,i:[]});
    } else {
      recs.push({c:'go',t:'Perfusion adequate',w:'No current trigger to escalate. Continue monitoring, wean support as tolerated.',i:[]});
    }

    // preload / fluid responsiveness
    if(!isNaN(s.svv)){
      if(s.svv>13) recs.push({c:'info',t:'Likely fluid responsive',w:'SVV/PPV '+s.svv+'% suggests preload responsiveness — but a small controlled challenge is safer than a bolus in the stiff post-op ventricle. SVV is unreliable with arrhythmia, spontaneous effort, low tidal volume or an open chest, and is shifted by vasoactives (venous tone).',i:[]});
      else recs.push({c:'info',t:'Unlikely fluid responsive',w:'SVV/PPV '+s.svv+'% — further volume unlikely to raise output; treat with tone / contractility, not fluid. Caveat: SVV low with venoconstrictors even when truly hypovolaemic.',i:[]});
    }

    if(ph.name==='VASOPLEGIA'){
      if(hypo&&!s.inf.norad.on) recs.push({c:'warn',t:'Start noradrenaline',w:'First-line vasopressor for perfusion pressure.',i:['Titrate to MAP ≥ 65']});
      if(s.inf.norad.on&&!s.inf.vaso.on) recs.push({c:'go',t:'Add vasopressin',w:'VANCS — vasopressin preferred over noradrenaline in post-cardiotomy vasoplegic shock (less morbidity).',i:['Add ~0.03 U/min, ceiling ~0.04 U/min']});
      if(s.inf.vaso.on&&!isNaN(s.inf.vaso.dose)&&s.inf.vaso.dose>0.04) recs.push({c:'warn',t:'Vasopressin above ceiling',w:'Running >0.04 U/min — little added benefit, digital/splanchnic ischaemia risk.',i:['Hold rate; escalate by a different mechanism']});
      if(s.inf.norad.on&&s.inf.vaso.on&&hypo) recs.push({c:'warn',t:'Refractory vasoplegia',w:'On two vasopressors and still hypotensive — broaden the mechanism and re-hunt for a cause.',i:['Hydrocortisone 50 mg qds (relative adrenal insufficiency)','Methylene blue 1–2 mg/kg (guanylate cyclase / NO pathway)','Angiotensin II','Re-exclude bleeding / sepsis / missed mechanical cause']});
    }
    if(ph.name==='LV FAILURE'){
      if(hypo&&!s.inf.norad.on) recs.push({c:'warn',t:'Restore perfusion pressure',w:'Defend MAP before/with inotropy — protect coronary perfusion (CPP = DBP − PAOP'+(!isNaN(d.cpp)?' = '+d.cpp.toFixed(0)+' mmHg':'')+').',i:['Noradrenaline to MAP ≥ 65']});
      if(!s.inf.dobut.on&&!s.inf.milrin.on) recs.push({c:'go',t:'Start an inotrope',w:'Cold, high-afterload LV needs contractility'+(!isNaN(d.lvswi)?' (LVSWI '+d.lvswi.toFixed(0)+' g·m/m² — low = poor LV work)':'')+'.',i:['Dobutamine, OR','Milrinone (inodilator) if not markedly hypotensive and RV not the problem — also lowers PVR & PAOP']});
    }
    if(ph.name==='RV FAILURE'){
      recs.push({c:'info',t:'Protect the RV',w:'RV afterload is PVR, not SVR. Drop PVR while defending aortic root pressure for RV coronary perfusion.'+(!isNaN(d.pvr)?' PVR '+d.pvr.toFixed(0)+(!isNaN(d.dpg)?', DPG '+d.dpg.toFixed(0)+' (>7 = precapillary component)':'')+'.':''),
        i:['Avoid over-filling (offload if CVP high / septal shift)','Reduce PVR: iNO / inhaled prostacyclin / milrinone; optimise oxygenation, avoid hypercarbia & acidosis','Inotrope: dobutamine or milrinone'+(!isNaN(d.rvswi)?' (RVSWI '+d.rvswi.toFixed(1)+')':'')]});
      if(hypo&&!s.inf.vaso.on) recs.push({c:'go',t:'Add vasopressin to defend SVR',w:'Raises SVR (RV coronary perfusion) without raising PVR — the preferred pressor in RV failure.',i:['Vasopressin ~0.03 U/min']});
      if(!isNaN(d.papi)&&d.papi<1.0) recs.push({c:'warn',t:'Low PAPi',w:'PAPi '+d.papi.toFixed(1)+' — marker of RV failure and higher likelihood of needing RV mechanical support. Escalate the RV plan early.',i:[]});
    }
    if(ph.name==='MIXED / BIVENT'){
      if(!s.inf.norad.on) recs.push({c:'warn',t:'Noradrenaline for pressure',w:'',i:['Titrate to MAP ≥ 65']});
      if(!s.inf.dobut.on&&!s.inf.milrin.on) recs.push({c:'go',t:'Add an inotrope',w:'Biventricular impairment — support contractility on both fronts.',i:['Dobutamine or milrinone']});
      if(!s.inf.vaso.on&&hypo) recs.push({c:'info',t:'Consider vasopressin',w:'Second pressor mechanism if catecholamine load is climbing.',i:[]});
    }
    if(ph.name==='INDETERMINATE'){
      recs.push({c:'info',t:'Get the numbers',w:'Phenotype is firmest with CI + SVRI. Enter both, or an echo flag, to direct agent choice.',i:['CI + SVRI → distinguishes pump vs tone','PASP/PADP + CVP → PAPi (RV) · height → CPO/DO₂i','Echo → RV, LV, SAM, tamponade']});
    }

    // oxygen delivery
    if((!isNaN(d.o2er)&&d.o2er>0.35)||(!isNaN(d.do2i)&&d.do2i<400)){
      recs.push({c:'warn',t:'Oxygen delivery inadequate',
        w:'High extraction / low delivery'+((!isNaN(d.o2er))?' (O₂ER '+(d.o2er*100).toFixed(0)+'%':'')+((!isNaN(d.do2i))?', DO₂i '+d.do2i.toFixed(0)+' mL/min/m²':'')+((!isNaN(d.o2er)||!isNaN(d.do2i))?')':'')+' — the tissues are compensating for inadequate supply.',
        i:['Raise CO (the phenotype-directed step above)','Correct anaemia — transfuse toward target Hb','Optimise SaO₂ and reduce avoidable O₂ demand (sedation, temperature, work of breathing)']});
    }
    // lactate clearance
    if(!isNaN(d.lacRate)){
      if(d.lacRate<10) recs.push({c:'warn',t:'Lactate not clearing',w:'Clearance '+d.lacClr.toFixed(0)+'% over '+s.dth+' h ('+d.lacRate.toFixed(0)+'%/h). <10%/h with ongoing support marks inadequate resuscitation or a missed source.',i:[]});
      else recs.push({c:'go',t:'Lactate clearing',w:'Clearance '+d.lacClr.toFixed(0)+'% over '+s.dth+' h — resuscitation trending the right way; continue and wean as tolerated.',i:[]});
    }

    if(s.inf.dobut.on&&s.inf.milrin.on){
      recs.push({c:'info',t:'Two inodilators running',w:'Dobutamine + milrinone give additive inodilation but also additive vasodilation — ensure vasopressor cover, watch SVR/MAP, and remember milrinone accumulates in renal impairment.',i:[]});
    }

    // four-agent escalation gate
    if(persistLow && (ph.name==='LV FAILURE'||ph.name==='RV FAILURE'||ph.name==='MIXED / BIVENT')){
      const ctx=[];
      if(!isNaN(d.cpo)) ctx.push('CPO '+d.cpo.toFixed(2)+' W'+(d.cpo<0.6?' (<0.6 severe)':''));
      if(!isNaN(d.papi)) ctx.push('PAPi '+d.papi.toFixed(1)+(d.papi<1.0?' (<1.0 high RV-failure risk)':''));
      if(L.complete){
        let dev, ecmo=false;
        if(ph.name==='RV FAILURE'||(!isNaN(d.papi)&&d.papi<1.0)){dev='RVAD / ProtekDuo (± oxygenator); VA-ECMO if biventricular'; if(ph.name==='MIXED / BIVENT')ecmo=true;}
        else if(ph.name==='LV FAILURE') dev=(!isNaN(d.cpo)&&d.cpo<0.6)?'Impella (active LV unloading) or IABP':'IABP → Impella';
        else {dev='VA-ECMO (± LV vent)'; ecmo=true;}
        recs.push({c:'alarm',t:'Four-agent ladder complete — escalate',
          w:'Vasopressin + adrenaline + dobutamine + milrinone all at therapeutic dose with persistent hypoperfusion.'+(ctx.length?' '+ctx.join(' · ')+'.':''),
          i:['Levosimendan as rescue adjunct — 0.1 µg/kg/min, usually no bolus if borderline BP; effect via active metabolite OR-1896 persists days (LEVO-CTS: ↓LCOS, no survival benefit)','Device by phenotype: '+dev,'Involve surgery + perfusion now']});
        if(ecmo||ph.name==='MIXED / BIVENT'){
          recs.push({c:'warn',t:'On VA-ECMO — pre-empt LV distension',w:'Retrograde flow raises LV afterload; an unloaded, non-ejecting LV distends, drives pulmonary oedema and stasis thrombus.',
            i:['Watch: loss of arterial pulsatility (PP <10–15), rising PADP/PAOP, pulmonary oedema, no aortic-valve opening, LV smoke on echo','Vent early: IABP, Impella (ECPELLA), pigtail/atrial septostomy, or surgical vent']});
        }
      } else {
        const miss=L.rungs.filter(r=>r.state!=='done').map(r=>r.name+(r.state==='sub'?' (uptitrate)':' (start)'));
        recs.push({c:'warn',t:'Complete the four-agent ladder before levosimendan / MCS',
          w:'Reserve levosimendan and mechanical support until vasopressin, adrenaline, dobutamine and milrinone are all at therapeutic dose.'+(ctx.length?' '+ctx.join(' · ')+'.':''),
          i:['Outstanding: '+miss.join(', ')]});
      }
    }

    // refractory differential
    if(st.s==='D'||st.s==='E'||(persistLow&&L.complete)){
      recs.push({c:'alarm',t:'Not responding — sweep for a reversible cause',
        w:'Before accepting refractory shock, actively re-exclude the fixable. Deterioration on adequate support is a cause you have not found yet, until proven otherwise.',
        i:['Mechanical: tamponade / clot, graft kink or occlusion, prosthetic dysfunction, dynamic LVOT/SAM','Volume/bleeding: occult haemorrhage, retroperitoneal / chest, coagulopathy','Ischaemia: new RWMA, ST shift, coronary spasm/air','Metabolic: acidosis, K⁺/Mg²⁺/iCa²⁺, hypoxia, hypocarbia/hypercarbia','Endocrine: relative adrenal insufficiency; anaphylaxis','Airway/thorax: pneumothorax, dynamic hyperinflation','Rhythm: AF/flutter, loss of AV synchrony, pacing failure (Module 06)','Iatrogenic: line/pump/drug error, wrong concentration']});
    }
  }
  // --- adrenaline: the lactate / glucose trap, continue vs stop ---
  if(s.inf.adr.on){
    const lacRising = s.lactTrend==='rising' || ((!isNaN(s.lac)&&s.lac>2) && s.lactTrend!=='falling');
    const perfOk = (!isNaN(s.svo2)&&s.svo2>=65)||(!isNaN(s.ci)&&s.ci>=2.2)||(!isNaN(d.cpo)&&d.cpo>=0.6)||(!isNaN(d.o2er)&&d.o2er<=0.30);
    const perfBad = (!isNaN(s.svo2)&&s.svo2<60)||(!isNaN(s.ci)&&s.ci<2.2)||(!isNaN(d.cpo)&&d.cpo<0.6)||(!isNaN(d.o2er)&&d.o2er>0.4)||(!isNaN(s.uo)&&s.uo<0.5);
    const hyperG = !isNaN(s.glu)&&s.glu>10;
    const adrDone = L.rungs.find(r=>r.key==='adr'&&r.state==='done');
    if(lacRising){
      if(perfBad && !perfOk){
        recs.push({c:'alarm', t:'Rising lactate on adrenaline \u2014 delivery is failing (type A)',
          w:'SvO\u2082 / CI / CPO / O\u2082ER point to real hypoperfusion, not the drug. Adrenaline is not achieving flow \u2014 do not simply uptitrate on the lactate.',
          i:['Confirm the four-agent ladder and sweep reversible contributors','Cut O\u2082 demand; treat arrhythmia; restore AV synchrony','Escalate toward mechanical support rather than chasing adrenaline dose','Weigh adrenaline\u2019s arrhythmic / metabolic cost against the flow it buys']});
      } else if(perfOk){
        recs.push({c:'cyan', t:'Rising lactate on adrenaline \u2014 likely type B (drug / glucose)',
          w:(hyperG?'Delivery looks adequate and the glucose is high':'Delivery looks adequate')+' \u2014 adrenaline drives \u03b2\u2082 glycolysis and hyperglycaemia, so this lactate is often the drug, not worsening perfusion.',
          i:['Control the glucose with insulin, then recheck the lactate trend',(isNaN(s.glu)?'Check a glucose \u2014 the adrenaline lactate tracks with it':'Track SvO\u2082 / CI / CPO and lactate clearance, not the absolute value'),'Continue adrenaline if it is holding CI / CPO / MAP \u2014 do not reflexively escalate','If it buys no haemodynamic benefit, swap to a cleaner inotrope or escalate support']});
      } else {
        recs.push({c:'warn', t:'Rising lactate on adrenaline \u2014 separate type A from type B',
          w:'Delivery markers are incomplete. Adrenaline can raise lactate and glucose directly (type B) independent of perfusion.',
          i:['Get SvO\u2082 / CI / CPO and a glucose to tell hypoperfusion from the drug effect','Adequate delivery + high glucose \u2192 type B: control glucose, hold escalation','Failing delivery \u2192 type A: treat as hypoperfusion and escalate']});
      }
    }
    if(adrDone && perfOk){
      recs.push({c:'go', t:'Adrenaline \u2014 consider weaning',
        w:'Delivery looks adequate on current support. Adrenaline is later-line (after noradrenaline + milrinone) and the first catecholamine to come off.',
        i:['Wean if function has recovered on noradrenaline + milrinone alone','Wean sooner with tachyarrhythmia / ectopy, or a type-B lactate that is clouding assessment','Leave noradrenaline + milrinone as the maintenance pairing']});
    }
  }
  // --- rising CVP: milrinone up, adrenaline down, noradrenaline up (RV manoeuvre) ---
  if(s.cvpTrend==='rising'){
    const adrOn=s.inf.adr.on, milOn=s.inf.milrin.on, norOn=s.inf.norad.on;
    const items=[];
    items.push(milOn?'Uptitrate milrinone \u2014 the inodilator augments the RV and lowers PVR (RV afterload)':'Start milrinone \u2014 inodilator: augments the RV and lowers PVR (RV afterload)');
    items.push(adrOn?'Reduce adrenaline \u2014 it raises PVR and myocardial O\u2082 demand and is arrhythmogenic; weaning it offloads the RV (mind the type-B lactate)':'Avoid escalating adrenaline \u2014 it raises PVR and RV demand');
    items.push(norOn?'Uptitrate noradrenaline \u2014 hold systemic (RV coronary) perfusion pressure as milrinone vasodilates; relatively PVR-neutral (vasopressin is the PVR-sparing alternative)':'Add noradrenaline \u2014 defend systemic (RV coronary) perfusion pressure as milrinone vasodilates (vasopressin is the PVR-sparing alternative)');
    items.push('Reduce PVR in parallel: O\u2082, correct hypercarbia / acidosis, consider iNO / inhaled prostacyclin');
    items.push('Do not volume-load the rising CVP \u2014 the distended RV shifts the septum and impairs LV filling; offload if over-filled');
    recs.push({c:'warn', t:'Rising CVP \u2014 shift to milrinone + noradrenaline, wean adrenaline',
      w:'A climbing CVP signals RV strain / venous congestion. Move the inotrope strategy off adrenaline (raises PVR + demand) onto milrinone (inodilator, lowers PVR), and hold perfusion pressure with noradrenaline \u2014 milrinone + noradrenaline / vasopressin is the RV combination.',
      i:items});
  }
  return recs;
}


function concPerMl(a,v,units){
  if(!(a>0)||!(v>0)) return NaN;
  return units ? a/v : a*1000/v;
}

function rateToDose(rate,cpmv,wt,weightBased){
  if(!(cpmv>0)||!(rate>=0)) return NaN;
  return weightBased ? rate*cpmv/((wt||70)*60) : rate*cpmv/60;
}

function doseToRate(dose,cpmv,wt,weightBased){
  if(!(cpmv>0)||!(dose>=0)) return NaN;
  return weightBased ? dose*(wt||70)*60/cpmv : dose*60/cpmv;
}

function neEquiv(o){
  return (o.norad||0)+(o.adr||0)+(o.dopa||0)/100+(o.phenyl||0)/10+(o.vaso||0)*2.5;
}

function visScore(o,wt){
  return (o.dopa||0)+(o.dobut||0)+100*((o.adr||0)+(o.norad||0))+10*(o.milrin||0)+10000*((o.vaso||0)/(wt||70));
}

function cvFmt(x){
  if(!isFinite(x)) return '\u2014';
  const a=Math.abs(x);
  if(a===0) return '0';
  if(a<1) return x.toFixed(3);
  if(a<10) return x.toFixed(2);
  if(a<100) return x.toFixed(1);
  return x.toFixed(0);
}

function dvCalc(v){
  const n=(x)=>{const y=parseFloat(x);return isNaN(y)?NaN:y;};
  const wt=n(v.wt),ht=n(v.ht),map=n(v.map),dbp=n(v.dbp),hr=n(v.hr),cvp=n(v.cvp),pasp=n(v.pasp),padp=n(v.padp),paop=n(v.paop),hb=n(v.hb),sao2=n(v.sao2),svo2=n(v.svo2),pao2=n(v.pao2);
  let co=n(v.co),ci=n(v.ci);
  const bsa=(!isNaN(wt)&&!isNaN(ht))?0.007184*Math.pow(wt,0.425)*Math.pow(ht,0.725):NaN;
  if(isNaN(co)&&!isNaN(ci)&&!isNaN(bsa))co=ci*bsa;
  if(isNaN(ci)&&!isNaN(co)&&!isNaN(bsa))ci=co/bsa;
  const mpap=(!isNaN(pasp)&&!isNaN(padp))?padp+(pasp-padp)/3:NaN;
  const sv=(!isNaN(co)&&hr>0)?co/hr*1000:NaN;
  const svi=(!isNaN(sv)&&!isNaN(bsa))?sv/bsa:NaN;
  const svr=(!isNaN(map)&&!isNaN(cvp)&&co>0)?(map-cvp)*80/co:NaN;
  const svri=(!isNaN(map)&&!isNaN(cvp)&&ci>0)?(map-cvp)*80/ci:NaN;
  const pvr=(!isNaN(mpap)&&!isNaN(paop)&&co>0)?(mpap-paop)*80/co:NaN;
  const pvrwu=(!isNaN(pvr))?pvr/80:NaN;
  const pvri=(!isNaN(mpap)&&!isNaN(paop)&&ci>0)?(mpap-paop)*80/ci:NaN;
  const tpg=(!isNaN(mpap)&&!isNaN(paop))?mpap-paop:NaN;
  const dpg=(!isNaN(padp)&&!isNaN(paop))?padp-paop:NaN;
  const papi=(!isNaN(pasp)&&!isNaN(padp)&&cvp>0)?(pasp-padp)/cvp:NaN;
  const cpo=(!isNaN(map)&&!isNaN(co))?map*co/451:NaN;
  const cpi=(!isNaN(map)&&!isNaN(ci))?map*ci/451:NaN;
  const lvswi=(!isNaN(svi)&&!isNaN(map)&&!isNaN(paop))?svi*(map-paop)*0.0136:NaN;
  const rvswi=(!isNaN(svi)&&!isNaN(mpap)&&!isNaN(cvp))?svi*(mpap-cvp)*0.0136:NaN;
  const cpp=(!isNaN(dbp)&&!isNaN(paop))?dbp-paop:NaN;
  const cao2=(!isNaN(hb)&&!isNaN(sao2))?1.34*(hb/10)*(sao2/100)+(!isNaN(pao2)?0.003*pao2:0):NaN;
  const cvo2=(!isNaN(hb)&&!isNaN(svo2))?1.34*(hb/10)*(svo2/100):NaN;
  const do2i=(!isNaN(ci)&&!isNaN(cao2))?ci*cao2*10:NaN;
  const vo2i=(!isNaN(ci)&&!isNaN(cao2)&&!isNaN(cvo2))?ci*(cao2-cvo2)*10:NaN;
  const o2er=(!isNaN(sao2)&&!isNaN(svo2)&&sao2>0)?(sao2-svo2)/sao2*100:NaN;
  return {bsa,co,ci,sv,svi,svr,svri,pvr,pvrwu,pvri,mpap,tpg,dpg,papi,cpo,cpi,lvswi,rvswi,cpp,cao2,do2i,vo2i,o2er};
}

function dvBand(k,x){
  const d=DVDEFS.find(q=>q.k===k);
  if(!d||isNaN(x))return '';
  if(x<d.lo)return 'lo';
  if(isFinite(d.hi)&&x>d.hi)return 'hi';
  return 'ok';
}

function outHTML(s,d,sc,ph,st,L,recs){
  const mapV=!isNaN(s.map)?Math.round(s.map):'—';
  let html='<div class="scores">'+
    tile(mapV,'MAP','≥65', (!isNaN(s.map)&&s.map<65)?css('--alarm'):css('--go'))+
    tile(fmt(s.ci,1),'CI','≥2.2',css('--cyan'))+
    tile(fmt(d.cpo,2),'CPO','W ≥0.6', (!isNaN(d.cpo)&&d.cpo<0.6)?css('--alarm'):'')+
    tile(sc.vis.toFixed(0),'VIS', sc.vis>20?'high load':sc.vis>10?'moderate':'low')+
    tile(sc.nee.toFixed(2),'NE-eq','µg/kg/min')+
    '</div>';

  html+=`<div class="pheno" style="border-color:${css(ph.col)}"><div><div class="badge" style="color:${css(ph.col)}">${ph.name}</div><div class="hint">${ph.conf}</div></div>`+
    `<div class="scai"><b style="color:${st.s==='E'?css('--alarm'):st.s==='D'?css('--warn'):css('--cyan')}">SCAI ${st.s}</b><div class="hint">${st.l}</div></div></div>`;

  html+='<div class="subhead">Resuscitation goals</div><div class="ladder">'+goals(s,d)+'</div>';

  const so=startOrder(s,d,ph,L);
  const ordPos={}; so.order.forEach((k,ix)=>{ordPos[k]=ix+1;});
  html+='<div class="subhead">Escalation ladder — start order is phenotype-directed</div>';
  html+='<div class="ladder">'+L.rungs.map(r=>{
    const cls=r.state==='done'?'done':r.state==='sub'?'miss':'';
    const isNext=so.next===r.key;
    const mk=r.state==='done'?'✓':r.state==='sub'?'▲':'○';
    const suf=r.state==='sub'?' · uptitrate':'';
    const ord=ordPos[r.key]?`<span class="ord">${ordPos[r.key]}</span>`:'';
    return `<span class="rung ${cls}${isNext?' next':''}">${ord}${mk} ${r.name}${suf}</span>`;
  }).join('')+'</div>';
  if(so.deferred){
    html+=`<div class="startadvice"><span class="seq">${so.note}</span></div>`;
  } else if(so.order.length){
    const chain=so.order.map((k,ix)=>`${ix+1}. ${AGENTNAME[k]}`).join('  →  ');
    let line;
    if(!so.next){ line='<b class="go">✓ Ladder complete</b> — all four at therapeutic dose; proceed to the levosimendan / MCS gate.'; }
    else { const verb=so.nextState==='sub'?'Uptitrate':'Start next'; const why=so.why[so.next]?(' — '+so.why[so.next]):''; line=`▶ <b class="go">${verb}: ${AGENTNAME[so.next]}</b>${why}`; }
    html+=`<div class="startadvice">${line}<br><span class="seq">Order (${ph.name}, after first-line noradrenaline): ${chain}</span>${so.note?`<br><span class="seq">${so.note}</span>`:''}</div>`;
  }

  const di=[
    ['SVRI',fmt(d.svri,0)+(d.svriCalc?'*':''),'dyn·s·cm⁻⁵·m²'],['SVI',fmt(d.svi,0),'mL/m²'],
    ['LVSWI',fmt(d.lvswi,0),'g·m/m²'],['RVSWI',fmt(d.rvswi,1),'g·m/m²'],
    ['PAPi',fmt(d.papi,1),'≥1.0'],['PVR',fmt(d.pvr,0),'dyn·s·cm⁻⁵'],
    ['DPG',fmt(d.dpg,0),'≤7'],['DO₂i',fmt(d.do2i,0),'mL/min/m²'],
    ['O₂ER',isNaN(d.o2er)?'—':(d.o2er*100).toFixed(0)+'%','≤30%'],['CPP',fmt(d.cpp,0),'DBP−PAOP'],
  ];
  html+='<div class="subhead">Derived indices'+(d.svriCalc?' · *SVRI computed':'')+'</div><div class="scores">'+
    di.map(x=>tile(x[1],x[0],x[2],'')).join('')+'</div>';

  recs.forEach(r=>{
    html+=`<div class="rec ${r.c}"><h4>${r.t}</h4>`;
    if(r.w) html+=`<div class="why">${r.w}</div>`;
    if(r.i&&r.i.length) html+='<ul>'+r.i.map(x=>`<li>${x}</li>`).join('')+'</ul>';
    html+='</div>';
  });
  const conf=(ph.conf==='CI+SVRI'||ph.conf==='CI+SVRI+echo'||ph.conf==='CI+SVRI+PA')?'high confidence':'add CI/SVRI for confidence';
  return {html, conf};
}


function build(v, flags, inf, fund) {
  const N = (x) => { const t = ("" + x).trim(); return t === "" ? NaN : parseFloat(t); };
  let map = N(v.map), sbp = NaN, dbp = NaN;
  if (("" + v.sbpdbp).includes("/")) {
    const p = ("" + v.sbpdbp).split("/").map(parseFloat);
    if (!isNaN(p[0])) sbp = p[0];
    if (!isNaN(p[1])) dbp = p[1];
    if (isNaN(map) && !isNaN(sbp) && !isNaN(dbp)) map = dbp + (sbp - dbp) / 3;
  }
  const infN = {};
  INF.forEach((d) => (infN[d.id] = { on: inf[d.id].on, dose: N(inf[d.id].dose) }));
  return {
    map, sbp, dbp, hr: N(v.hr), lac: N(v.lac), lactTrend: v.lactrend, glu: N(v.glu),
    prevlac: N(v.prevlac), dth: N(v.dth), svo2: N(v.svo2), sao2: N(v.sao2), hb: N(v.hb),
    uo: N(v.uo), svv: N(v.svv), ci: N(v.ci), svri: N(v.svri), cvp: N(v.cvp), cvpTrend: v.cvptrend,
    paop: N(v.paop), pasp: N(v.pasp), padp: N(v.padp), wt: N(v.wt) || 70, ht: N(v.ht),
    flags, fund, inf: infN,
  };
}
function analyze(v, flags, inf, fund, light) {
  THEME_LIGHT = !!light;
  const s = build(v, flags, inf, fund);
  const d = deriv(s);
  const sc = scores(s);
  const ph = phenotype(s, d);
  const anySupport = INF.some((x) => s.inf[x.id].on) || s.flags.arrest;
  const st = scai(s, d, anySupport);
  const L = ladderState(s);
  const recs = computeRecs(s, d, sc, ph, st, L);
  const o = outHTML(s, d, sc, ph, st, L, recs);
  return { html: o.html, conf: o.conf };
}

