function Converter() {
  const [drug, setDrug] = useState("norad");
  const d = DRUGS.find((x) => x.id === drug);
  const [concIdx, setConcIdx] = useState("0");
  const [amt, setAmt] = useState(String(d.concs[0].a));
  const [vol, setVol] = useState(String(d.concs[0].v));
  const [wt, setWt] = useState("");
  const [rate, setRate] = useState("");
  const [dose, setDose] = useState("");
  const [src, setSrc] = useState("rate");
  const [ne, setNe] = useState({ norad:"", adr:"", dopa:"", dobut:"", milrin:"", phenyl:"", vaso:"", wt:"" });
  const N = (x) => { const v = parseFloat(x); return isNaN(v) ? NaN : v; };

  const cpmv = concPerMl(N(amt), N(vol), d.units);
  const wtN = N(wt) || 70;
  const compDose = rateToDose(N(rate), cpmv, wtN, d.wt);
  const compRate = doseToRate(N(dose), cpmv, wtN, d.wt);
  const rateVal = src === "rate" ? rate : (isFinite(compRate) ? cvFmt(compRate) : "");
  const doseVal = src === "dose" ? dose : (isFinite(compDose) ? cvFmt(compDose) : "");
  const shownDose = N(doseVal);
  const cpmTxt = (isFinite(cpmv) && cpmv > 0) ? cvFmt(cpmv) + (d.units ? " U/mL" : " \u00b5g/mL") : "\u2014";
  let rangeCls = "cv-range", rangeTxt = "";
  if (isFinite(shownDose) && shownDose > 0) {
    const rng = d.lo + "\u2013" + d.hi + " " + d.unit;
    if (shownDose < d.lo) { rangeCls = "cv-range warn"; rangeTxt = "below usual range (" + rng + ")"; }
    else if (shownDose > d.hi) { rangeCls = "cv-range alarm"; rangeTxt = "above usual range (" + rng + ")"; }
    else { rangeCls = "cv-range ok"; rangeTxt = "within usual range (" + rng + ")"; }
  }
  const pickDrug = (id) => { const nd = DRUGS.find((x) => x.id === id); setDrug(id); setConcIdx("0"); setAmt(String(nd.concs[0].a)); setVol(String(nd.concs[0].v)); };
  const pickConc = (v) => { setConcIdx(v); if (v !== "custom") { const c = d.concs[+v]; setAmt(String(c.a)); setVol(String(c.v)); } };
  const neO = { norad:N(ne.norad)||0, adr:N(ne.adr)||0, dopa:N(ne.dopa)||0, dobut:N(ne.dobut)||0, milrin:N(ne.milrin)||0, phenyl:N(ne.phenyl)||0, vaso:N(ne.vaso)||0 };
  const neVal = neEquiv(neO), visVal = visScore(neO, N(ne.wt) || 70);
  const setNeF = (k, v) => setNe((o) => ({ ...o, [k]: v }));
  const NEROWS = [["norad","Noradrenaline","\u00b5g/kg/min"],["adr","Adrenaline","\u00b5g/kg/min"],["dopa","Dopamine","\u00b5g/kg/min"],["dobut","Dobutamine","\u00b5g/kg/min"],["milrin","Milrinone","\u00b5g/kg/min"],["phenyl","Phenylephrine","\u00b5g/kg/min"],["vaso","Vasopressin","U/min"],["wt","Weight","kg"]];

  return (
    <section className="module on" id="m-conv">
      <div className="eyebrow">Module 09 · bedside utility</div>
      <h2>Dose converter — inotropes &amp; vasopressors</h2>
      <p className="lead">Two-way conversion between infusion rate and dose for the common agents, a noradrenaline-equivalent / VIS quick calc, and the standard concentrations. Weight- and concentration-aware; each agent carries its own units.</p>
      <div className="grid g2">
        <div className="panel">
          <h3>Rate ⇄ dose <span className="tag">edit either side</span></h3>
          <div className="fieldgrid">
            <div className="field"><label>Agent</label>
              <select value={drug} onChange={(e) => pickDrug(e.target.value)}>{DRUGS.map((x) => <option key={x.id} value={x.id}>{x.nm}</option>)}</select></div>
            <div className="field"><label>Concentration <span className="unit">preset</span></label>
              <select value={concIdx} onChange={(e) => pickConc(e.target.value)}>{d.concs.map((c, i) => <option key={i} value={i}>{c.l}</option>)}<option value="custom">custom…</option></select></div>
            <div className="field"><label>Drug amount <span className="unit">{d.units ? "U" : "mg"}</span></label><input inputMode="decimal" value={amt} onChange={(e) => setAmt(e.target.value)} /></div>
            <div className="field"><label>Diluent volume <span className="unit">mL</span></label><input inputMode="decimal" value={vol} onChange={(e) => setVol(e.target.value)} /></div>
            {d.wt && <div className="field"><label>Weight <span className="unit">kg</span></label><input inputMode="decimal" placeholder="70" value={wt} onChange={(e) => setWt(e.target.value)} /></div>}
          </div>
          <div className="cv-io">
            <div className="field"><label>Rate <span className="unit">mL/h</span></label><input inputMode="decimal" placeholder="—" value={rateVal} onChange={(e) => { setSrc("rate"); setRate(e.target.value); }} /></div>
            <div className="cv-eq">⇄</div>
            <div className="field"><label>Dose <span className="unit">{d.unit}</span></label><input inputMode="decimal" placeholder="—" value={doseVal} onChange={(e) => { setSrc("dose"); setDose(e.target.value); }} /></div>
          </div>
          <div className="cv-meta"><span>Concentration: <b>{cpmTxt}</b></span><span className={rangeCls}>{rangeTxt}</span></div>
        </div>
        <div className="panel">
          <h3>Noradrenaline-equivalent &amp; VIS <span className="tag">enter running doses</span></h3>
          <div className="fieldgrid">
            {NEROWS.map(([k, lab, u]) => <div className="field" key={k}><label>{lab} <span className="unit">{u}</span></label><input inputMode="decimal" placeholder={k === "wt" ? "70" : "0"} value={ne[k]} onChange={(e) => setNeF(k, e.target.value)} /></div>)}
          </div>
          <div className="cv-meta"><span>NE-equivalent: <b>{neVal > 0 ? cvFmt(neVal) + " \u00b5g/kg/min" : "\u2014"}</b></span><span>VIS: <b>{(visVal > 0 && isFinite(visVal)) ? cvFmt(visVal) : "\u2014"}</b></span></div>
          <p className="hint">NE-eq = NA + Adr + dopamine/100 + phenylephrine/10 + vasopressin×2.5. VIS = dopamine + dobutamine + 100·(Adr+NA) + 10·milrinone + 10000·vasopressin(U/kg/min). Equivalency is approximate — a titration guide, not a fixed exchange rate.</p>
        </div>
      </div>
      <div className="panel sec">
        <h3>Standard concentrations &amp; usual ranges</h3>
        <div className="tbl-wrap"><table><tbody>
          <tr><th>Agent</th><th>Common dilutions</th><th>Usual range</th></tr>
          {DRUGS.map((x) => <tr key={x.id}><td><b>{x.nm}</b></td><td dangerouslySetInnerHTML={{ __html: x.concs.map((c) => c.l + " = " + cvFmt(concPerMl(c.a, c.v, x.units)) + (x.units ? " U/mL" : " \u00b5g/mL")).join("<br>") }} /><td className="mono">{x.lo}\u2013{x.hi} {x.unit}</td></tr>)}
        </tbody></table></div>
      </div>
      <p className="disc">Bedside aid — always cross-check against your unit's standard-concentration chart and an independent calculation before changing a rate. The concentrations shown are common examples, not a substitute for the prescribed dilution.</p>
    </section>
  );
}

